import {test} from 'node:test';import assert from 'node:assert/strict';
import {createPyramidTerrain} from '../terrain/pyramid.ts';
import {polyhedronMaterial} from '../surfaces/polyhedron-material.ts';
import {polyhedronHoleAt,resizePolyhedronHole} from '../surfaces/polyhedron-holes.ts';
import {polyhedronMapLink} from '../surfaces/polyhedron-passages.ts';
import {PolyhedronConnectionStore} from './polyhedron-connection-store.ts';
import {validatePolyhedronConnections,polyhedronConnectionWords,decodePolyhedronConnectionWords} from './polyhedron-connections.ts';
import {SolidPyramidSession} from './pyramid-session.ts';
import {createConnectedHistory} from './connected-history.ts';
import {preparePyramidDab} from '../terrain/pyramid-brush.ts';
function fixture(hollow=false){const identity={worldId:'connection-pyramid',surfaceId:'outer'},exterior=createPyramidTerrain({terrainId:'outer-terrain',geometry:{provider:'physical-square-pyramid',version:1,identity,role:'exterior',baseWidthMeters:2e6,heightMeters:1.6e6,baseZMeters:0},subdivisions:32,initialElevation:0}),interior=hollow?createPyramidTerrain({terrainId:'inner-terrain',geometry:{...exterior.geometry.metadata,identity:{...identity,surfaceId:'inner'},role:'interior',baseWidthMeters:1.2e6,heightMeters:1e6,baseZMeters:1e5},subdivisions:32,initialElevation:0}):undefined,body=polyhedronMaterial(exterior.geometry,interior?.geometry);let busy=false,drains=0;const banks=interior?{exterior,interior}:{exterior},store=new PolyhedronConnectionStore(body,banks,{locked:()=>busy,setBusy:b=>{busy=b;},drain:async()=>{drains++;},changed:()=>{}});return{exterior,interior,body,store,get busy(){return busy;},get drains(){return drains;},anchor:{...identity,patchId:'south' as const,u:.3,v:.3}};}
test('physical publication, preview and bit-exact bounded history preserve unrelated terrain and real bank ownership',async()=>{
 for(const hollow of[false,true]){const f=fixture(hollow),s=f.store,h=polyhedronHoleAt(f.body,f.anchor,5000),before=f.exterior.copyElevations(),revision=f.exterior.revision,next={...s.connections,holes:[h]};
  await s.checkConnections(next);assert.equal(s.connections.holes.length,0);assert.equal(s.geometryRevision,0);assert.equal(s.modified,false);assert.equal(f.busy,false);
  await s.changeConnections(next);const words=s.connectionWords.slice();assert.equal(s.connections.holes.length,1);assert.ok(s.connectionHistory.canUndo);assert.ok(s.modified);assert.equal(f.exterior.revision,revision);assert.deepEqual(f.exterior.copyElevations(),before);assert.equal(s.protectionBytes,f.exterior.sampleCount*(hollow?2:1));
  await s.replay();assert.equal(s.connections.holes.length,0);await s.replay(true);assert.deepEqual(s.connectionWords,words);assert.equal(s.connections.holes[0]!.id,h.id);
  await s.changeConnections({...s.connections,holes:[resizePolyhedronHole(f.body,h,6000)]});await s.replay();assert.deepEqual(s.connectionWords,words);
  const journal=s.connectionHistory.exportJournal(),other=fixture(hollow);await other.store.restoreConnections(s.connections,journal);assert.equal(other.store.modified,false);assert.deepEqual(other.store.connectionHistory.exportJournal(),journal);await other.store.replay(true);assert.equal(other.store.connections.holes[0]!.radiusMeters,6000);s.dispose();other.store.dispose();
 }
});
test('ground checks and prepared patches reject atomically; replay cannot restore a cut onto displaced ground',async()=>{
 const f=fixture(),s=f.store,h=polyhedronHoleAt(f.body,f.anchor,5000),next={...s.connections,holes:[h]},key=f.exterior.resolve({...f.anchor,row:10,column:10});f.exterior.write(key,-0);const zeroWords=new Uint32Array(f.exterior.copyElevations().buffer);await s.changeConnections(next);assert.throws(()=>f.exterior.write(key,1),/protected/);
 const unrelated=[...f.exterior.samples()].find(k=>{try{f.exterior.write(k,10);f.exterior.write(k,0);return true;}catch{return false;}})!;assert.ok(unrelated);const indices=[key.index,unrelated.index].toSorted((a,b)=>a-b),revision=f.exterior.revision,words=new Uint32Array(f.exterior.copyElevations().buffer);assert.throws(()=>f.exterior.commitPreparedPatch(key,revision,[{indices:Uint32Array.from(indices),values:Float32Array.of(50,50),count:2}]),/protected/);assert.equal(f.exterior.revision,revision);assert.deepEqual(new Uint32Array(f.exterior.copyElevations().buffer),words);assert.equal(new Uint32Array(f.exterior.copyElevations().buffer)[key.index],zeroWords[key.index]);
 await s.replay();f.exterior.write(key,12);const state=s.connectionHistory.stateId;await assert.rejects(s.replay(true),/exactly 0 m/);assert.equal(s.connectionHistory.stateId,state);assert.equal(s.connections.holes.length,0);assert.equal(s.connectionHistory.canRedo,true);assert.equal(f.busy,false);f.exterior.write(key,-0);await s.replay(true);assert.equal(s.connections.holes.length,1);s.dispose();
});
test('identity collisions, unknown fields, sparse lists and noncanonical history reject without publication',async()=>{
 const f=fixture(),s=f.store,h=polyhedronHoleAt(f.body,f.anchor,5000),l=polyhedronMapLink(f.body,f.anchor,{kind:'map-location',worldId:'external',mapId:'map',locationId:'door'});assert.throws(()=>validatePolyhedronConnections(f.body,{holes:[h],passages:[],links:[{...l,id:h.id}]}));assert.throws(()=>validatePolyhedronConnections(f.body,{...s.connections,holes:[h,h]}));assert.throws(()=>validatePolyhedronConnections(f.body,{...s.connections,links:new Array(1)}));assert.throws(()=>validatePolyhedronConnections(f.body,{...s.connections,extra:true} as never));
 await s.changeConnections({...s.connections,links:[l]});const before=s.connectionWords.slice(),journal=s.connectionHistory.exportJournal(),bad=structuredClone(journal);(bad.undo[0]!.before as number[])[0]=0xffffffff;await assert.rejects(s.restoreConnections(s.connections,bad));assert.deepEqual(s.connectionWords,before);assert.deepEqual(s.connectionHistory.exportJournal(),journal);
 const canonical=polyhedronConnectionWords(s.connections);assert.deepEqual(decodePolyhedronConnectionWords(canonical),s.connections);await assert.rejects(s.changeConnections({...s.connections,holes:[{...h,worldId:'foreign'}]}));assert.equal(f.busy,false);assert.deepEqual(s.connectionWords,before);s.dispose();
});
test('an overlapping host Save/unlock cannot release the solid terrain lock during a connection transaction',async()=>{const f=fixture(),session=new SolidPyramidSession(f.exterior,'Lock test'),s=session.connectionStore,link=polyhedronMapLink(s.body,f.anchor,{kind:'map-location',worldId:'external',mapId:'map',locationId:'door'}),update=s.changeConnections({...s.connections,links:[link]});assert.equal(session.locked,true);session.locked=true;session.locked=false;assert.equal(session.locked,true);await assert.rejects(session.drainForSave(),/Wait/);await update;assert.equal(session.locked,false);assert.equal(s.connections.links.length,1);session.dispose();});
test('existing numerical Flatten history cannot undo protected zero ground until the physical cut is removed',async()=>{const f=fixture(true),s=f.store,h=polyhedronHoleAt(f.body,f.anchor,5000),entries=h.mouths.map(m=>{const t=m.position.surfaceId==='outer'?f.exterior:f.interior!,key=t.resolve({...t.geometry.identity,patchId:m.position.patchId as 'south',row:Math.round(m.position.v*t.subdivisions),column:Math.round(m.position.u*t.subdivisions)});t.write(key,12);const history=createConnectedHistory(t),operation=history.beginOperation(t),center=t.positionAt(t.owner(key)),job=preparePyramidDab(t,center,{version:1,tool:'flatten',radiusMeters:150000,intensity:1,targetElevation:0});while(job.status==='preparing')job.pump(64);operation.commitDab(job);operation.finish('released');assert.equal(t.read(key),0);return{t,key,history};});await s.changeConnections({...s.connections,holes:[h]});for(const e of entries){const before=e.t.copyElevations(),cursor=e.history.statistics.cursor,revision=e.t.revision;assert.throws(()=>e.history.undo(),/protected/);assert.equal(e.history.statistics.cursor,cursor);assert.equal(e.t.revision,revision);assert.deepEqual(e.t.copyElevations(),before);}await s.changeConnections({...s.connections,holes:[]});for(const e of entries){assert.equal(e.history.undo(),true);assert.equal(e.t.read(e.key),12);assert.equal(e.history.redo(),true);assert.equal(e.t.read(e.key),0);}s.dispose();});
